ALTER TABLE public.diagnostic_triggers ADD COLUMN IF NOT EXISTS dicas jsonb NOT NULL DEFAULT '[]'::jsonb;
UPDATE public.diagnostic_triggers SET dicas = '["Tente incluir fibras (aveia, chia, vegetais) em todas as refeições — elas seguram a glicose e evitam o pico que te deixa com fome 1h depois. E olha: cortar doce de vez é mito; o segredo é trocar (fruta + canela mata vontade em 80% dos casos).", "Açúcar e farinha branca são gatilhos diretos do seu quadro. Comece pelo café da manhã: troque pão branco por integral + ovo. Só essa mudança já estabiliza sua glicose pela manhã toda.", "Caminhar 15 min depois das refeições reduz o pico glicêmico em até 30%. Não precisa de academia — só sair da cadeira. Combina com proteína em cada refeição e você muda o jogo em semanas."]'::jsonb WHERE slug = 'diabetes';
UPDATE public.diagnostic_triggers SET dicas = '["Não conte calorias agora — comece por proteína em todas as refeições (mão fechada de peito, ovo, peixe). Saciedade aumenta, fome cai e o peso começa a descer sozinho.", "Beba água ANTES de cada refeição (300ml). Estudo da Universidade de Birmingham mostrou perda média de 4kg em 12 semanas só com isso. Simples e gratuito.", "Durma 7h+. Pesquisa real: dormir menos eleva grelina (hormônio da fome) em 28%. Você não tem fraqueza — tem privação de sono. Resolve o sono e metade da batalha já tá ganha."]'::jsonb WHERE slug = 'imc_sobrepeso';
UPDATE public.diagnostic_triggers SET dicas = '["Ganhar peso saudável não é comer porcaria. Adicione 1 lanche calórico-denso por dia: pasta de amendoim + banana + aveia bate 500kcal limpas.", "Foque em proteína (1,6g/kg) + treino de força 3x/semana. Sem treino, o ganho vira gordura. Com treino, vira músculo — e isso muda corpo e autoestima.", "Coma a cada 3h. Seu metabolismo provavelmente é acelerado; espaçar refeições sabota o ganho. Programa alarme no celular nas primeiras 2 semanas."]'::jsonb WHERE slug = 'imc_abaixo';
UPDATE public.diagnostic_triggers SET dicas = '["Você está no peso — agora vem a parte boa: composição corporal. Treino de força + 1,6g de proteína/kg muda como você se vê no espelho mesmo com a balança parada.", "Mantenha 80/20: 80% comida de verdade, 20% liberdade. Dietas 100% restritivas não duram — equilíbrio sim.", "Pesa-se 1x por semana, mesmo horário. Foque em medidas e fotos mensais — são indicadores melhores que a balança."]'::jsonb WHERE slug = 'imc_ideal';
UPDATE public.diagnostic_triggers SET dicas = '["Café da manhã com proteína (ovos, queijo, iogurte grego) muda seu dia todo: reduz pico de insulina, melhora ciclo e diminui aquela fome doida de tarde. Comece por aí.", "Inositol (mio + d-chiro) é estudado pra SOP — vale conversar com seu médico. Combinado com redução de açúcar refinado, muitas mulheres regulam ciclo em 3-6 meses.", "Treino de força é melhor que cardio infinito. SOP responde melhor a musculação 3x/semana do que esteira 1h. Sensibilidade à insulina sobe em poucas semanas."]'::jsonb WHERE slug = 'sop_insulina';
UPDATE public.diagnostic_triggers SET dicas = '["O vilão não é só o sal do saleiro — é o sódio escondido (embutidos, temperos prontos, congelados). Leia rótulos por 1 semana e você se assusta. Cozinhar em casa derruba sua pressão.", "Aumente potássio: banana, abacate, batata-doce, espinafre. Potássio equilibra sódio e relaxa vasos. Resultado em 2-3 semanas, sem remédio extra.", "Café tudo bem — álcool não. 2 doses já elevam pressão por 24h. Reduzir álcool é a mudança de maior impacto + menor esforço pra hipertenso."]'::jsonb WHERE slug = 'hipertensao';
UPDATE public.diagnostic_triggers SET dicas = '["Tome levotiroxina em jejum, 30-60min antes do café. Cálcio, ferro e café atrapalham absorção — espalhe esses pela tarde.", "Selênio (castanha-do-pará, 2/dia) e zinco apoiam conversão T4 para T3. Não exagera na castanha: 2 por dia é o ideal, mais que isso vira tóxico.", "Glúten pode piorar Hashimoto em parte das pessoas. Teste 30 dias sem glúten e veja como se sente — não é regra, mas vale o experimento."]'::jsonb WHERE slug = 'tireoide';
UPDATE public.diagnostic_triggers SET dicas = '["Não deite por 2h após comer. Janta cedo (até 20h se dorme às 22h). Só isso resolve refluxo noturno em muita gente.", "Identifique seu gatilho: café, tomate, pimenta, chocolate, álcool são os clássicos. Tira 1 por vez por 1 semana e vê a diferença.", "Mastiga MUITO. 20-30x por garfada. A digestão começa na boca — engolir rápido sobrecarrega estômago e piora refluxo."]'::jsonb WHERE slug = 'gastrite_refluxo';
UPDATE public.diagnostic_triggers SET dicas = '["Compulsão quase sempre vem de: dormiu mal + pulou refeição + estresse. Resolva os 3 e a compulsão some sozinha — não é força de vontade, é fisiologia.", "Proteína no café da manhã (ovos, iogurte grego) reduz compulsão à noite em 60%. Estudo real. Tenta 1 semana e me conta.", "Quando bater a vontade: 1 copo de água + caminhar 5 min. Se ainda quiser depois, come. 70% das vezes a vontade some — era sede, tédio ou ansiedade."]'::jsonb WHERE slug = 'compulsao';
UPDATE public.diagnostic_triggers SET dicas = '["Regra simples: 35ml × seu peso em kg = sua meta diária. Pesa 70kg? 2,45L. Garrafa de 500ml ao lado do trabalho — meta é 5 dessas.", "Não gosta de água? Põe rodela de limão, hortelã, gengibre. Chá gelado sem açúcar conta. Café e refri NÃO contam (desidratam).", "Beba antes de ter sede. Sede já é desidratação. Alarme de 2 em 2h no celular nas primeiras 2 semanas até virar hábito."]'::jsonb WHERE slug = 'agua_baixa';
UPDATE public.diagnostic_triggers SET dicas = '["Fibra + água. Uma sem a outra empedra. 25-30g de fibra/dia (aveia, chia, frutas com casca, vegetais) + 2L de água. Em 1 semana o intestino acorda.", "Kefir ou iogurte natural diário repõe microbiota. Probiótico caseiro, barato e funciona melhor que cápsula em muitos casos.", "Coma devagar e sem distração. Engolir ar com a comida (celular, tv, ansiedade) é causa principal de inchaço pós-refeição."]'::jsonb WHERE slug = 'intestino_inchaco';
UPDATE public.diagnostic_triggers SET dicas = '["Cheque ferritina, B12 e vitamina D no próximo exame. 80% do cansaço crônico vem de uma dessas 3. Reposição muda sua vida em semanas.", "Café da manhã com proteína (não só pão+café) sustenta energia até o almoço sem bater aquela sonolência de 10h.", "Cansaço pode ser desidratação. Antes de tomar mais café, bebe 500ml de água. Surpreendentemente eficaz."]'::jsonb WHERE slug = 'energia_baixa';
UPDATE public.diagnostic_triggers SET dicas = '["Não precisa virar atleta. Comece com 7000 passos/dia — pesquisa mostra que isso já reduz mortalidade em 50% vs sedentário. Caminhada conta.", "Treino de força 2x/semana, 30min. Músculo é o órgão da longevidade — queima calorias 24h, protege articulações e melhora postura.", "Sem tempo? 10min pela manhã + 10min à noite. Funciona. O melhor treino é o que você faz."]'::jsonb WHERE slug = 'sedentarismo';
UPDATE public.diagnostic_triggers SET dicas = '["Sem tela 1h antes de dormir. Luz azul bloqueia melatonina por 90min. Livro, banho quente, alongamento — qualquer coisa exceto celular.", "Cafeína corta às 14h. Meia-vida do café é 6h — aquele cafézinho das 17h ainda tá no seu sangue às 23h sabotando o sono.", "Quarto frio (18-20°C), escuro e silencioso. Temperatura corporal precisa cair pra dormir. Ar condicionado + cortina blackout = mudança radical."]'::jsonb WHERE slug = 'sono_ruim';
UPDATE public.diagnostic_triggers SET dicas = '["Pular café da manhã não emagrece — só atrasa a compulsão pra noite. Comece com algo simples: ovos + fruta. 5 min e tá resolvido.", "Espaça refeições em 3-4h. Manhã, almoço, lanche, jantar. Sem pular. Glicemia estável = fome controlada = sem ataques noturnos.", "Prepara lanches na segunda pra semana toda: ovo cozido, fruta, castanha, iogurte. Ter opção saudável à mão é 90% da batalha."]'::jsonb WHERE slug = 'refeicoes_poucas';
UPDATE public.diagnostic_triggers SET dicas = '["Foco em PROTEÍNA e FIBRA em cada refeição. Esses 2 dão saciedade real. Calorias caem sozinhas sem fome.", "Pesa-se 1x por semana, mesmo dia/horário, sem roupa, após banheiro. Diário enlouquece (peso oscila 2kg num dia normal).", "Sem dieta-relâmpago. Perder 0,5-1kg/semana é o sweet spot — mais que isso, perde músculo e volta tudo. Paciência paga."]'::jsonb WHERE slug = 'objetivo_emagrecer';
UPDATE public.diagnostic_triggers SET dicas = '["Superávit de 300-500kcal/dia. Mais que isso vira gordura. Menos que isso, não cresce. Calcula direito e respeita.", "Proteína: 1,6-2,2g por kg de peso. 70kg = 110-150g de proteína/dia. Distribui em 4-5 refeições — corpo só absorve 30-40g por vez.", "Treina pesado. Hipertrofia precisa de estímulo progressivo (carga subindo). Sem treino bom, comer mais só engorda."]'::jsonb WHERE slug = 'objetivo_ganhar_massa';
UPDATE public.diagnostic_triggers SET dicas = '["Café da manhã com proteína + gordura boa + fibra (ovos + abacate + aveia). Energia estável até o almoço, sem queda de 10h.", "Hidratação é energia. 1% de desidratação = 10% menos energia mental. Garrafa sempre por perto.", "Sol pela manhã 10-15min. Regula cortisol, melatonina e disposição o dia todo. Grátis e mais potente que muito suplemento."]'::jsonb WHERE slug = 'objetivo_energia';